const listChangelogEntries = `-- name: ListChangelogEntries :many
SELECT e.id, e.workspace_id, e.changelog_id, e.number, e.labels, e.image_id, e.state, e.publish_at, e.published_at, e.scheduled_by_member_id, e.scheduled_by_api_key_id, e.schedule_failed, e.schedule_failed_at, e.created_by_member_id, e.created_by_api_key_id, e.created_at, e.updated_at FROM changelog_entries e
WHERE e.workspace_id = $1 AND e.changelog_id = $2
  AND ($3::text IS NULL OR CASE $3::text
      WHEN 'changed' THEN e.state = 'published' AND EXISTS (
          SELECT 1 FROM changelog_entry_translations t
          WHERE t.workspace_id = e.workspace_id AND t.entry_id = e.id AND t.has_unpublished_changes
            AND ($4::text IS NULL OR t.locale = $4::text))
      ELSE e.state = $3::text END)
  AND ($5::text IS NULL OR $5::text = ANY (e.labels))
  AND ($4::text IS NULL OR EXISTS (
      SELECT 1 FROM changelog_entry_translations t
      WHERE t.workspace_id = e.workspace_id AND t.entry_id = e.id AND t.locale = $4::text))
  AND ($6::int IS NULL OR e.number < $6::int)
ORDER BY e.number DESC
LIMIT $7
`

type ListChangelogEntriesParams struct {
	WorkspaceID  uuid.UUID
	ChangelogID  uuid.UUID
	State        *string
	Locale       *string
	Label        *string
	CursorNumber *int32
	Lim          int32
}

func (q *Queries) ListChangelogEntries(ctx context.Context, arg ListChangelogEntriesParams) ([]ChangelogEntry, error) {
	rows, err := q.db.Query(ctx, listChangelogEntries,
		arg.WorkspaceID,
		arg.ChangelogID,
		arg.State,
		arg.Locale,
		arg.Label,
		arg.CursorNumber,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ChangelogEntry
	for rows.Next() {
		var i ChangelogEntry
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.ChangelogID,
			&i.Number,
			&i.Labels,
			&i.ImageID,
			&i.State,
			&i.PublishAt,
			&i.PublishedAt,
			&i.ScheduledByMemberID,
			&i.ScheduledByApiKeyID,
			&i.ScheduleFailed,
			&i.ScheduleFailedAt,
			&i.CreatedByMemberID,
			&i.CreatedByApiKeyID,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

